INSERT INTO public.discover_sections (id, lang, title, subtitle, sort_order, is_active, created_at, updated_at) VALUES ('91555a37-15f9-413f-80a0-cf2d7805c86a', 'zh', '存在与虚无', NULL, 4, TRUE, '2026-04-26T01:42:02.472959+00:00', '2026-04-30T15:45:54.287728+00:00') ON CONFLICT (id) DO UPDATE SET lang = EXCLUDED.lang, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, sort_order = EXCLUDED.sort_order, is_active = EXCLUDED.is_active, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO public.soulers (id, name, canonical_name, lang, wiki_id, checked, bio, created_at, updated_at) VALUES ('d91e3cb8-7a8e-48ff-aa48-112be199d580', '加缪', '阿尔贝·加缪', 'zh', 'Q34670', TRUE, '阿尔贝·加缪（Albert Camus，1913–1960）是法国作家、哲学家、记者，也是存在主义思潮的重要代表人物之一（尽管他本人更倾向于自称为“荒诞哲学家”）。出生于法属阿尔及利亚的贫寒家庭，加缪的早期经历深刻影响了他对生命、死亡与人类处境的思考。他的思想核心围绕“荒诞”展开：在一个没有上帝、缺乏内在意义的宇宙中，人类却本能地渴望意义与秩序，这种根本性的冲突构成了生存的荒诞性。\r\n\r\n在《西西弗神话》中，加缪以希腊神话中永无止境推石上山的西西弗为喻，指出面对荒诞，人不应选择自杀或宗教式的逃避（即“哲学自杀”），而应通过清醒的认知与反抗，在无意义中创造属于自己的意义。他强调“反抗”并非为了推翻某种秩序，而是对人性尊严的坚守，是对不公与虚无的持续说“不”。\r\n\r\n加缪的文学创作与其哲学思想紧密交织。小说《局外人》塑造了默尔索这一冷漠疏离的形象，揭示了社会规范对个体真实情感的压抑；《鼠疫》则通过一场瘟疫寓言，探讨了在集体灾难面前人类的团结、责任与道德选择。他反对暴力革命与极权主义，主张一种基于人道主义与适度原则的伦理立场。\r\n\r\n1957 年，加缪因“其重要的文学创作，以明察的真诚阐明了我们时代人类良心的种种问题”获得诺贝尔文学奖。他的作品以其清晰的风格、深刻的洞察力和对人性的温情关怀，持续激励着人们在困境中寻找光明与尊严。', '2026-04-24T09:15:02.397253+00:00', '2026-04-24T09:15:51.063833+00:00') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, canonical_name = EXCLUDED.canonical_name, lang = EXCLUDED.lang, wiki_id = EXCLUDED.wiki_id, checked = EXCLUDED.checked, bio = EXCLUDED.bio, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO public.soulers (id, name, canonical_name, lang, wiki_id, checked, bio, created_at, updated_at) VALUES ('3dfa0019-6de0-42d1-a01a-0853fd6d679b', '卡夫卡', '弗兰兹·卡夫卡', 'zh', 'Q905', TRUE, '弗兰兹·卡夫卡（Franz Kafka，1883–1924）是出生于布拉格的德语犹太作家，被公认为现代主义文学的奠基人之一。他的创作生涯短暂且充满孤独，大部分作品在其去世后才由好友马克斯·布罗德整理出版。卡夫卡的小说以荒诞、压抑和梦魇般的氛围著称，深刻描绘了个体在庞大、冷漠且不可理喻的官僚体制或命运面前的无力感与异化处境。\r\n\r\n在他的代表作《变形记》中，主人公格里高尔一觉醒来变成甲虫，这一超现实设定隐喻了人在现代社会中丧失主体性、沦为工具后的悲惨境遇；而在《审判》与《城堡》中，他构建了没有尽头、逻辑混乱的迷宫式世界，人物在其中徒劳地寻求真相或准入许可，却始终无法触及权力的核心。这种“卡夫卡式”（Kafkaesque）的风格，精准捕捉了现代人面对未知恐惧、罪责感以及沟通失效时的精神困境。\r\n\r\n卡夫卡的文字冷静克制，却蕴含着巨大的情感张力。他并未直接批判社会制度，而是通过极致的寓言形式，揭示了人类存在的根本性焦虑：我们渴望意义与归属，却往往被困在无意义的规则与疏离的关系网中。他的作品超越了时代，成为理解二十世纪乃至当代人类精神危机的重要钥匙，对存在主义哲学、荒诞派戏剧及后世文学产生了深远影响。', '2026-04-24T10:21:38.65411+00:00', '2026-04-24T10:28:34.706264+00:00') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, canonical_name = EXCLUDED.canonical_name, lang = EXCLUDED.lang, wiki_id = EXCLUDED.wiki_id, checked = EXCLUDED.checked, bio = EXCLUDED.bio, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO public.soulers (id, name, canonical_name, lang, wiki_id, checked, bio, created_at, updated_at) VALUES ('f9c7c63f-0c0a-4287-b6a2-63040078c2de', '尼采', '弗里德里希·尼采', 'zh', 'Q9358', TRUE, '弗里德里希·尼采（Friedrich Nietzsche，1844–1900）是德国哲学家、文化批评家与诗性思想家。他最初以古典语文学者的身份进入学界，但很早便转向对西方文明根基的深度反思。他批判基督教道德与传统哲学，认为这些体系压抑了生命本能与个体力量，并提出“上帝已死”，用以指代旧有意义与价值体系的瓦解。在这种崩塌之中，人类将不可避免地面对虚无主义——即意义缺失与价值真空的处境。\r\n\r\n尼采并未停留在否定之中，他进一步提出“权力意志”，将其视为生命最根本的驱动力，即不断扩张、自我强化与创造的冲动。在此基础上，他区分“主人道德”与“奴隶道德”，揭示道德并非绝对真理，而是不同生命状态与权力关系的产物。\r\n\r\n在重建层面，尼采提出“超人”概念，象征能够摆脱既有价值、独立创造意义的人。他强调“成为你自己”，主张个体不断进行自我超越，在持续的否定与重塑中生成新的存在形态。同时，他以“永恒回归”作为极限命题：如果一个人的人生需要被无限重复，他是否仍愿意肯定它？这一思想最终指向“命运之爱”（Amor fati）——不仅接受命运，更主动热爱一切发生过的事。\r\n\r\n尼采的思想具有强烈的张力与诗性表达，他并不提供稳定答案，而是通过不断的质疑、撕裂与重构，将个体推向更深层的自我审视与存在觉醒。他的影响跨越哲学、文学、心理学与现代文化，被视为理解现代性危机与个体精神困境的重要思想源头之一。', '2026-04-24T09:08:29.178824+00:00', '2026-04-24T09:11:01.908113+00:00') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, canonical_name = EXCLUDED.canonical_name, lang = EXCLUDED.lang, wiki_id = EXCLUDED.wiki_id, checked = EXCLUDED.checked, bio = EXCLUDED.bio, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO public.soulers (id, name, canonical_name, lang, wiki_id, checked, bio, created_at, updated_at) VALUES ('a0ea4fec-1db5-48c3-8b3e-e4f0180dccda', '海德格尔', '马丁·海德格尔', 'zh', 'Q48301', TRUE, '马丁·海德格尔（Martin Heidegger，1889–1976）是 20 世纪最具影响力的德国哲学家之一，存在主义现象学的奠基人。他的核心关切在于重新追问“存在的意义”，试图打破自柏拉图以来西方形而上学对“存在者”的沉迷而遗忘“存在”本身的传统。在其代表作《存在与时间》中，他通过分析“此在”（Dasein）——即人的具体生存状态，揭示了人是被“抛”入世界的，并在与世界的互动中展开其可能性。\r\n\r\n海德格尔深刻剖析了现代技术的本质，认为技术不仅仅是一种工具，更是一种将世界视为可计算、可操控资源的“座架”思维，这种思维导致了人与自然、人与自身本真关系的异化。他提出“向死而生”的概念，指出只有直面死亡的必然性，个体才能从日常的沉沦中觉醒，回归本真的生存方式。\r\n\r\n后期海德格尔转向对语言、艺术与诗的沉思，认为“语言是存在的家”，真理并非简单的符合论，而是存在的自行显现（去蔽）。他的思想深邃且充满歧义，既开启了当代解释学与后结构主义的先河，也因其纳粹时期的政治卷入而备受争议。无论如何，他对技术时代人类生存困境的洞察，至今仍是哲学反思的重要资源。', '2026-04-30T12:44:15.676664+00:00', '2026-04-30T12:47:22.711392+00:00') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, canonical_name = EXCLUDED.canonical_name, lang = EXCLUDED.lang, wiki_id = EXCLUDED.wiki_id, checked = EXCLUDED.checked, bio = EXCLUDED.bio, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
INSERT INTO public.soulers (id, name, canonical_name, lang, wiki_id, checked, bio, created_at, updated_at) VALUES ('bc6e92a2-2d0e-4313-a121-7ed9220d0bce', '萨特', '让-保罗·萨特', 'zh', 'Q9364', TRUE, '让 - 保罗·萨特（Jean-Paul Sartre，1905–1980）是法国存在主义哲学家、剧作家、小说家及社会活动家，20 世纪最具影响力的思想家之一。他确立了存在主义的核心命题：“存在先于本质”，意指人并非生来具有固定的本性或目的，而是首先存在于世，随后通过自由的选择与行动来定义自己。萨特强调，人是绝对自由的，这种自由伴随着沉重的责任，因为个体必须独自承担所有选择的后果，无法将责任推卸给上帝、命运或人性。\r\n\r\n在《存在与虚无》中，萨特深入剖析了意识的结构，提出了“自为”（pour-soi）与“自在”（en-soi）的区别，并揭示了人类面对自由时产生的“焦虑”以及试图逃避自由责任的“自欺”（mauvaise foi）。他认为，人总是处于一种欠缺状态，不断追求成为某种确定的存在，但这永远无法完全实现。\r\n\r\n除了哲学理论，萨特还积极投身政治与社会运动，关注殖民主义、阶级斗争与人权问题。尽管他在 1964 年被授予诺贝尔文学奖，但他以“拒绝一切来自官方的荣誉”为由坚决拒领，以保持其作为独立知识分子的立场。萨特的思想深刻塑造了战后欧洲的精神面貌，推动了人道主义存在主义的发展，并持续启发着关于自由、责任与伦理的现代讨论。', '2026-04-28T08:47:45.380047+00:00', '2026-04-28T08:48:54.671669+00:00') ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, canonical_name = EXCLUDED.canonical_name, lang = EXCLUDED.lang, wiki_id = EXCLUDED.wiki_id, checked = EXCLUDED.checked, bio = EXCLUDED.bio, created_at = EXCLUDED.created_at, updated_at = EXCLUDED.updated_at;
